mod model; mod parser; mod indexer; mod render;
use std::{env,fs,path::{Path,PathBuf},io::Write};
fn safe(p:&str)->bool{let x=Path::new(p);x.is_absolute()&&!x.components().any(|c|matches!(c,std::path::Component::ParentDir))}
fn publish(path:&str,data:&str)->Result<(),()>{let p=Path::new(path);if fs::symlink_metadata(p).map(|m|m.file_type().is_symlink()).unwrap_or(false){return Err(());}let parent=p.parent().ok_or(())?;let mut tmp=PathBuf::from(parent);tmp.push(format!(".cubic-index-{}.tmp",std::process::id()));let result=(||{let mut f=fs::File::create(&tmp).map_err(|_|())?;f.write_all(data.as_bytes()).map_err(|_|())?;f.sync_all().map_err(|_|())?;fs::rename(&tmp,p).map_err(|_|())?;Ok(())})();if result.is_err(){let _=fs::remove_file(&tmp);}result}
fn main(){let a:Vec<String>=env::args().collect();if a.len()!=5||a[1]!="--study"||a[3]!="--output"{eprintln!("usage");std::process::exit(64);}if !safe(&a[2])||!safe(&a[4])||a[2]==a[4]{eprintln!("unsafe_path");std::process::exit(65);}let text=match fs::read_to_string(&a[2]){Ok(x)=>x,Err(_)=>{eprintln!("study:1:UNEXPECTED_EOF");std::process::exit(66)}};let study=match parser::parse(&text){Ok(x)=>x,Err((l,c))=>{eprintln!("study:{}:{}",l,c);std::process::exit(66)}};let plan=indexer::solve(&study);let out=render::render(&study,plan.as_ref());if publish(&a[4],&out).is_err(){eprintln!("output_error");std::process::exit(74)}}
